binding.script:
	lat = getprop("sim/model/f15/fcs/target-lat");
	lon = getprop("sim/model/f15/fcs/target-lon");
	alt = getprop("sim/model/f15/fcs/target-alt");
	if (lat < 90 and lat > -90 and lon < 180 and lon > -180 and pylons.fcs != nil) {
		var wp = pylons.fcs.getSelectedWeapon();
		if (wp != nil and wp.parents[0] == armament.AIM and wp.target_pnt == 1 and (wp.guidance=="gps" or wp.guidance=="gps-altitude")) {
			var coord = geo.Coord.new();
			coord.set_latlon(lat,lon,alt*FT2M);
			var spot = awg_9.ContactTGP.new("GPS-Spot",coord,0);
			armament.contactPoint = spot;
			tgp.gps = 1;
			if (getprop("sim/model/f15/stores/tgp-mounted") and 0) {
				tgp.flir_updater.click_coord_cam = armament.contactPoint.get_Coord();
				callsign = armament.contactPoint.getUnique();
                setprop("/sim/model/f15/flir/target/auto-track", 1);
                flir_updater.offsetP = 0;
                flir_updater.offsetH = 0;
				setprop("sim/model/f15/avionics/tgp-lock", 1);
			}
			wp.setContacts([spot]);
		}
	}

if (pylons.fcs != nil) {
	var wp = pylons.fcs.getSelectedWeapon();
	if (wp != nil and wp.parents[0] == armament.AIM) {
		wp.setContacts([]);
	}
	if (armament.contactPoint != nil and armament.contactPoint.get_Callsign()=="GPS-Spot") {
		armament.contactPoint = nil;
	}
	tgp.gps = 0;
	if (!getprop("sim/model/f15/stores/tgp-mounted")) {
		tgp.flir_updater.click_coord_cam = nil;
	}
}

				lat = getprop("sim/model/f15/fcs/target-lat");
				lon = getprop("sim/model/f15/fcs/target-lon");
				alt = getprop("sim/model/f15/fcs/target-alt");

				gps_spot = geo.Coord.new().set_latlon(lat,lon,alt*FT2M);
				datalink.send_data({"point": gps_spot}, timeout = 15);  # stops being continuously sent after 15 seconds

				# Notify the pilot and logs it
                var out = "Sending GPS-Spot over datalink. Timeout: 15 seconds.";
                var out_detailed = sprintf("Sending GPS-Spot over datalink. Timeout: 15 seconds. Lat: %.05f deg, Lon: %.05f deg, Alt: %.02f ft.", lat, lon, alt);
                screen.log.write(out, 1,1,0);
                print(out_detailed);
                damageLog.push(out_detailed);

var run = func() {
	foreach(gps_spot_cur ; awg_9.dtl_share_stpts) {
		if (gps_spot_cur.callsign == getprop("instrumentation/datalink/checked-callsign")) {
			setprop("instrumentation/datalink/checked-lat", gps_spot_cur.gps_spot.lat());
			setprop("instrumentation/datalink/checked-lon", gps_spot_cur.gps_spot.lon());
			setprop("instrumentation/datalink/checked-alt", gps_spot_cur.gps_spot.at());
			setprop("instrumentation/datalink/checked-found", "FOUND");
		} else {
			setprop("instrumentation/datalink/checked-found", "NOT FOUND");  # notify the user that no GPS-Spot of this name shared over datalink has been found
		}
	}
	if (size(awg_9.dtl_share_stpts) < 1) {
	    setprop("instrumentation/datalink/checked-found", "NOT FOUND");
	}
}
settimer(run, 1.5);  # wait for the property, just a safety

	lat = getprop("instrumentation/datalink/checked-lat");
	lon = getprop("instrumentation/datalink/checked-lon");
	alt = getprop("instrumentation/datalink/checked-alt");
	if (lat < 90 and lat > -90 and lon < 180 and lon > -180 and pylons.fcs != nil) {
		var wp = pylons.fcs.getSelectedWeapon();
		if (wp != nil and wp.parents[0] == armament.AIM and wp.target_pnt == 1 and (wp.guidance=="gps" or wp.guidance=="gps-altitude")) {
			var coord = geo.Coord.new();
			coord.set_latlon(lat,lon,alt*FT2M);
			var spot = awg_9.ContactTGP.new("GPS-Spot",coord,0);
			armament.contactPoint = spot;
			tgp.gps = 1;
			if (getprop("sim/model/f15/stores/tgp-mounted") and 0) {
				tgp.flir_updater.click_coord_cam = armament.contactPoint.get_Coord();
				callsign = armament.contactPoint.getUnique();
                setprop("/sim/model/f15/flir/target/auto-track", 1);
                flir_updater.offsetP = 0;
                flir_updater.offsetH = 0;
				setprop("sim/model/f15/avionics/tgp-lock", 1);
			}
			wp.setContacts([spot]);
		}
	}

if (pylons.fcs != nil) {
	var wp = pylons.fcs.getSelectedWeapon();
	if (wp != nil and wp.parents[0] == armament.AIM) {
		wp.setContacts([]);
	}
	if (armament.contactPoint != nil and armament.contactPoint.get_Callsign()=="GPS-Spot") {
		armament.contactPoint = nil;
	}
	tgp.gps = 0;
	if (!getprop("sim/model/f15/stores/tgp-mounted")) {
		tgp.flir_updater.click_coord_cam = nil;
	}
}
